+Quat
+pow(const Quat &q, int n)
+{
+	if (n > 1) {
+		int m = (n >> 1);
+		Quat r = pow(q, m);
+		r *= r;
+		// n odd
+		if (n & 1)
+			r *= q;
+		return r;
+	}
+
+	if (n == 1)
+		return q;
+
+	if (n == 0)
+		return Quat(1, 0, 0, 0);
+
+	// n < 0
+	return pow(Quat(1, 0, 0, 0) / q, -n);
+}
