+static int
+Quat_getbuffer(PyObject *obj, Py_buffer *view, int flags)
+{
+	if (view == NULL) {
+		PyErr_SetString(PyExc_ValueError, "NULL view");
+		return -1;
+	}
+
+	view->shape = NULL;
+
+	bp::handle<> self(bp::borrowed(obj));
+	bp::object selfobj(self);
+	bp::extract<Quat &> ext(selfobj);
+	if (!ext.check()) {
+		PyErr_SetString(PyExc_ValueError, "Invalid quat");
+		view->obj = NULL;
+		return -1;
+	}
+	Quat &q = ext();
+
+	view->obj = obj;
+	view->buf = (void*)&q;
+	view->len = 4 * sizeof(double);
+	view->readonly = 0;
+	view->itemsize = sizeof(double);
+	if (flags & PyBUF_FORMAT)
+		view->format = (char *)"d";
+	else
+		view->format = NULL;
+
+	view->ndim = 1;
+	view->internal = NULL;
+	view->shape = NULL;
+	view->strides = NULL;
+	view->suboffsets = NULL;
+
+	Py_INCREF(obj);
+
+	return 0;
+}
