+std::map<std::string, MetadataValue> SOMAArray::get_metadata() {
+    return metadata_;
+}
+
+bool SOMAArray::has_metadata(const std::string& key) {
+    return metadata_.count(key) != 0;
+}
+
+uint64_t SOMAArray::metadata_num() const {
+    return metadata_.size();
+}
